a:
Show cancellation via timeout, propagation, checking `Done`, and a typed value key:

```go
type ctxKey struct{}

func work(ctx context.Context, id int) error {
	reqID, _ := ctx.Value(ctxKey{}).(string)
	select {
	case <-time.After(time.Duration(id) * 300 * time.Millisecond):
		fmt.Println(reqID, "job", id, "done")
		return nil
	case <-ctx.Done():
		return fmt.Errorf("%s job %d: %w", reqID, id, ctx.Err())
	}
}

func main() {
	ctx := context.WithValue(context.Background(), ctxKey{}, "req-42")
	ctx, cancel := context.WithTimeout(ctx, time.Second)
	defer cancel()

	for i := 1; i <= 5; i++ {
		if err := work(ctx, i); err != nil {
			fmt.Println(err, errors.Is(err, context.DeadlineExceeded))
			return
		}
	}
}
```

Output:
```text
req-42 job 1 done
req-42 job 2 done
req-42 job 3: context deadline exceeded true
```
Jobs 1 and 2 take 300 ms + 600 ms; job 3 would end at 1.8 s, past the 1 s deadline. In real code the same `ctx` goes to `db.QueryContext` / `http.NewRequestWithContext`.
